/* ==UserStyle==
@name           GitHub Gruvbox Dark Soft
@namespace      github.com/openstyles/stylus
@version        1.0.0
@description    Comprehensive Gruvbox Dark Soft theme for GitHub.
@author         AI Assistant
@license        MIT
==/UserStyle== */
@-moz-document domain("github.com") {
:root {
        /* Gruvbox Dark Soft Palette */
        --gruvbox-bg0: #32302f;
        --gruvbox-bg1: #3c3836;
        --gruvbox-bg2: #504945;
        --gruvbox-bg3: #665c54;
        --gruvbox-bg4: #7c6f64;
        --gruvbox-fg0: #fbf1c7;
        --gruvbox-fg1: #ebdbb2;
        --gruvbox-fg2: #d5c4a1;
        --gruvbox-fg3: #bdae93;
        --gruvbox-fg4: #a89984;
        --gruvbox-red: #fb4934;
        --gruvbox-green: #b8bb26;
        --gruvbox-yellow: #fabd2f;
        --gruvbox-blue: #83a598;
        --gruvbox-purple: #d3869b;
        --gruvbox-aqua: #8ec07c;
        --gruvbox-orange: #fe8019;
        --gruvbox-gray: #928374;
        
        /* GitHub Variables Override */
        --color-canvas-default: var(--gruvbox-bg0);
        --color-canvas-overlay: var(--gruvbox-bg1);
        --color-canvas-inset: #282828;
        --color-canvas-subtle: var(--gruvbox-bg1);
        
        --color-fg-default: var(--gruvbox-fg1);
        --color-fg-muted: var(--gruvbox-fg4);
        --color-fg-subtle: var(--gruvbox-fg3);
        
        --color-border-default: var(--gruvbox-bg2);
        --color-border-muted: var(--gruvbox-bg3);
        --color-border-subtle: var(--gruvbox-bg2);
        
        --color-accent-fg: var(--gruvbox-blue);
        --color-accent-emphasis: var(--gruvbox-blue);
        --color-accent-muted: rgba(131, 165, 152, 0.4);
        --color-accent-subtle: rgba(131, 165, 152, 0.15);
        
        --color-success-fg: var(--gruvbox-green);
        --color-success-emphasis: var(--gruvbox-green);
        
        --color-attention-fg: var(--gruvbox-yellow);
        --color-attention-emphasis: var(--gruvbox-yellow);
        
        --color-danger-fg: var(--gruvbox-red);
        --color-danger-emphasis: var(--gruvbox-red);
        
        --color-done-fg: var(--gruvbox-purple);
        --color-done-emphasis: var(--gruvbox-purple);
        
        --color-neutral-emphasis: var(--gruvbox-gray);
        --color-neutral-muted: var(--gruvbox-bg2);
        
        --color-btn-bg: var(--gruvbox-bg2);
        --color-btn-text: var(--gruvbox-fg1);
        --color-btn-border: var(--gruvbox-bg3);
        --color-btn-hover-bg: var(--gruvbox-bg3);
        
        --color-btn-primary-bg: var(--gruvbox-green);
        --color-btn-primary-text: var(--gruvbox-bg0);
        --color-btn-primary-border: var(--gruvbox-green);
        --color-btn-primary-hover-bg: #98971a;
        
        --color-header-bg: var(--gruvbox-bg1);
        --color-header-text: var(--gruvbox-fg1);
        --color-header-logo: var(--gruvbox-fg1);
    }

    /* Global Body */
    body {
        background-color: var(--gruvbox-bg0) !important;
        color: var(--gruvbox-fg1) !important;
    }

    /* Headers */
    .Header, .header-logged-out, [role="banner"] {
        background-color: var(--gruvbox-bg1) !important;
        border-bottom: 1px solid var(--gruvbox-bg2) !important;
    }

    .Header-link {
        color: var(--gruvbox-fg1) !important;
    }

    .Header-link:hover {
        color: var(--gruvbox-blue) !important;
    }

    /* Search Bar */
    .header-search-wrapper {
        background-color: var(--gruvbox-bg0) !important;
        border-color: var(--gruvbox-bg3) !important;
    }

    /* Navigation Tabs */
    .UnderlineNav-item {
        color: var(--gruvbox-fg2) !important;
    }

    .UnderlineNav-item:hover {
        color: var(--gruvbox-fg0) !important;
        border-bottom-color: var(--gruvbox-bg4) !important;
    }

    .UnderlineNav-item[aria-current="page"], .UnderlineNav-item.selected {
        color: var(--gruvbox-orange) !important;
        border-bottom-color: var(--gruvbox-orange) !important;
    }

    /* Repository Boxes */
    .Box, .Box-header, .boxed-group-inner, .flash, .Popover-message {
        background-color: var(--gruvbox-bg1) !important;
        border-color: var(--gruvbox-bg2) !important;
    }

    .Box-header {
        background-color: var(--gruvbox-bg2) !important;
    }

    .Box-row--focus-gray.navigation-focus {
        background-color: var(--gruvbox-bg2) !important;
    }

    /* Buttons */
    .btn, .Button, .social-count {
        background-color: var(--gruvbox-bg2) !important;
        color: var(--gruvbox-fg1) !important;
        border-color: var(--gruvbox-bg3) !important;
    }

    .btn:hover, .Button:hover {
        background-color: var(--gruvbox-bg3) !important;
        border-color: var(--gruvbox-bg4) !important;
    }

    .btn-primary, .Button--primary {
        background-color: var(--gruvbox-green) !important;
        color: var(--gruvbox-bg0) !important;
        border-color: var(--gruvbox-green) !important;
    }

    .btn-primary:hover, .Button--primary:hover {
        background-color: #98971a !important;
    }

    /* Links */
    a, .link-ui {
        color: var(--gruvbox-blue) !important;
    }

    a:hover {
        color: var(--gruvbox-aqua) !important;
    }

    /* Markdown & Content */
    .markdown-body {
        color: var(--gruvbox-fg1) !important;
    }

    .markdown-body h1, .markdown-body h2, .markdown-body h3, .markdown-body h4, .markdown-body h5, .markdown-body h6 {
        color: var(--gruvbox-fg0) !important;
        border-bottom-color: var(--gruvbox-bg2) !important;
    }

    .markdown-body blockquote {
        border-left-color: var(--gruvbox-bg3) !important;
        color: var(--gruvbox-fg3) !important;
    }

    .markdown-body code, .markdown-body tt {
        background-color: var(--gruvbox-bg1) !important;
    }

    .markdown-body pre {
        background-color: #282828 !important;
    }

    /* Code Highlighting (General) */
    .pl-c { color: var(--gruvbox-gray) !important; } /* comment */
    .pl-s { color: var(--gruvbox-green) !important; } /* string */
    .pl-k { color: var(--gruvbox-red) !important; } /* keyword */
    .pl-v { color: var(--gruvbox-blue) !important; } /* variable */
    .pl-e, .pl-en { color: var(--gruvbox-aqua) !important; } /* function */
    .pl-pds { color: var(--gruvbox-green) !important; } /* string punctuation */
    .pl-smi { color: var(--gruvbox-fg1) !important; } /* identifier */
    .pl-ent { color: var(--gruvbox-orange) !important; } /* tag */
    .pl-mb { color: var(--gruvbox-fg0) !important; font-weight: bold !important; }
    .pl-mh { color: var(--gruvbox-orange) !important; font-weight: bold !important; }

    /* File Tree & Lists */
    .js-navigation-item:hover {
        background-color: var(--gruvbox-bg2) !important;
    }

    .react-directory-row:hover {
        background-color: var(--gruvbox-bg2) !important;
    }

    /* Labels & Badges */
    .Label, .badge {
        background-color: var(--gruvbox-bg2) !important;
        color: var(--gruvbox-fg2) !important;
        border-color: var(--gruvbox-bg3) !important;
    }

    /* Alerts */
    .flash-warn {
        background-color: rgba(250, 189, 47, 0.1) !important;
        border-color: var(--gruvbox-yellow) !important;
        color: var(--gruvbox-yellow) !important;
    }

    .flash-error {
        background-color: rgba(251, 73, 52, 0.1) !important;
        border-color: var(--gruvbox-red) !important;
        color: var(--gruvbox-red) !important;
    }

    /* Diff View */
    .blob-code-addition { background-color: rgba(184, 187, 38, 0.15) !important; }
    .blob-code-addition .x { background-color: rgba(184, 187, 38, 0.3) !important; }
    .blob-code-deletion { background-color: rgba(251, 73, 52, 0.15) !important; }
    .blob-code-deletion .x { background-color: rgba(251, 73, 52, 0.3) !important; }
    
    .blob-num-addition { background-color: rgba(184, 187, 38, 0.2) !important; border-color: var(--gruvbox-green) !important; }
    .blob-num-deletion { background-color: rgba(251, 73, 52, 0.2) !important; border-color: var(--gruvbox-red) !important; }

    /* Pull Requests & Issues */
    .TimelineItem-badge {
        background-color: var(--gruvbox-bg2) !important;
        border-color: var(--gruvbox-bg3) !important;
        color: var(--gruvbox-fg2) !important;
    }

    .TimelineItem::before {
        background-color: var(--gruvbox-bg2) !important;
    }

    /* Forms & Inputs */
    .form-control, .input-contrast {
        background-color: var(--gruvbox-bg0) !important;
        color: var(--gruvbox-fg1) !important;
        border-color: var(--gruvbox-bg3) !important;
    }

    .form-control:focus {
        border-color: var(--gruvbox-blue) !important;
        box-shadow: 0 0 0 3px rgba(131, 165, 152, 0.3) !important;
    }

    /* Footer */
    .footer {
        border-top-color: var(--gruvbox-bg2) !important;
    }

    /* Modal / Dialog */
    .Overlay, .SelectMenu-modal {
        background-color: var(--gruvbox-bg1) !important;
        border-color: var(--gruvbox-bg2) !important;
        box-shadow: 0 8px 24px rgba(0,0,0,0.5) !important;
    }
}

options.value:
/* Comfortable density - default GitHub spacing */
:root { --density-spacing: 1; }
.TimelineItem { padding-top: 16px; padding-bottom: 16px; }
.repository-content .container-xl { padding-left: 16px; padding-right: 16px; }

/* Compact density - tighter spacing */
:root { --density-spacing: 0.75; }
.TimelineItem { padding-top: 8px !important; padding-bottom: 8px !important; }
.repository-content .container-xl { padding-left: 8px !important; padding-right: 8px !important; }
.Box-header { padding: 8px 12px !important; }
.Sidebar .BorderGrid-cell { padding: 12px 0 !important; }
.commit-tease { padding: 6px 10px !important; }
.file-header { padding: 5px 10px !important; }

/* Spacious density - generous spacing */
:root { --density-spacing: 1.25; }
.TimelineItem { padding-top: 24px !important; padding-bottom: 24px !important; }
.repository-content .container-xl { padding-left: 24px !important; padding-right: 24px !important; }
.Box-header { padding: 16px 24px !important; }
.Sidebar .BorderGrid-cell { padding: 20px 0 !important; }
